const w = $('Pick And Record Winner').first().json;
const bin = $input.first().binary;
const hasImage = !!(bin && bin.data);
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const site = 'https://threetotango.canimi.app';
const isTest = /(@ttw-test\.invalid|\+ttwtest@gmail\.com)$/i.test(String(w.email || ''));
const pre = isTest ? '[TEST] ' : '';
const rawName = String(w.name || 'A cat').replace(/[\r\n]+/g, ' ');
const name = esc(rawName);
const shareUrl = site + '/tango-me/r/' + encodeURIComponent(w.id);
const caption = 'Cat of the Week: ' + rawName + ' 🏆 Moved in with Luka, Budy and Caddy — and survived. Put your cat in the show: threetotango.canimi.app/tango-me';
const wrap = (inner) => '<div style="font-family:Arial,sans-serif;max-width:480px;margin:0 auto;color:#222">' + inner + '</div>';
const btn = 'display:inline-block;padding:12px 22px;border-radius:8px;font-weight:bold;text-decoration:none;background:#E1AD01;color:#222;';
const ownerHtml = wrap('<h2 style="margin:0 0 8px">' + name + ' is Cat of the Week</h2>'
  + '<p style="color:#666">' + esc(w.likes) + ' likes in the last 7 days. Week of ' + esc(w.week_start) + '. The 9:16 story image is attached' + (hasImage ? '' : ' (could not be loaded)') + '.</p>'
  + '<p style="margin:16px 0 4px;font-weight:bold">Caption (copy and paste)</p>'
  + '<p style="background:#faf6ea;padding:12px;border-radius:8px;white-space:pre-wrap">' + esc(caption) + '</p>'
  + '<p style="margin:16px 0 4px;font-weight:bold">Share link</p>'
  + '<p><a href="' + esc(shareUrl) + '">' + esc(shareUrl) + '</a></p>');
const winnerHtml = wrap('<h2 style="margin:0 0 8px">' + name + ' is Cat of the Week 🏆</h2>'
  + '<p>Your cat got the most likes in the Three To Tango gallery this week.</p>'
  + '<p><img src="' + esc(site + '/media/tango/' + w.id + '-post.jpg') + '" alt="' + name + '" style="width:100%;max-width:480px;border-radius:8px"></p>'
  + '<p><a href="' + esc(shareUrl) + '">Share ' + name + '’s page</a></p>'
  + '<p style="margin:16px 0">You earned one more free Tango Me.</p>'
  + '<p><a href="' + esc(site + '/tango-me') + '" style="' + btn + '">Put another cat in the show</a></p>');
return [{ json: { winnerEmail: String(w.email || ''), sendWinner: !/@ttw-test\.invalid$/i.test(String(w.email || '')), ownerSubject: pre + 'Cat of the Week: ' + rawName + ' — story ready', ownerHtml, winnerSubject: pre + rawName + ' is Cat of the Week 🏆', winnerHtml, hasImage }, binary: hasImage ? { data: bin.data } : {} }];
